import React, { useEffect, useState } from "react";

function Packets() {
  const [packets, setPackets] = useState([]);

  useEffect(() => {
    fetch("http://127.0.0.1:8000/packets/")
      .then((res) => res.json())
      .then((data) => {
        setPackets(data.packets);
      });
  }, []);

  return (
    <div>
      <h1>Packets</h1>
      {packets.map((p, index) => (
        <div key={index}>
          {p.source_ip} → {p.destination_ip}
        </div>
      ))}
    </div>
  );
}

export default Packets;
